import{_ as s,a,b as i,c as d,d as n,e as l,f as p}from"./chunks/OOP_UI3.DGHtp2cm.js";import{_ as h,C as c,o as b,c as m,a3 as o,j as e,E as u,w as O}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Out of Process Algorithm","description":"","frontmatter":{},"headers":[],"relativePath":"use/OOP.md","filePath":"use/OOP.md"}'),g={name:"use/OOP.md"};function f(_,t,P,y,v,w){const r=c("big");return b(),m("div",null,[t[1]||(t[1]=o('<p>Out of process algorithms are external apps whose function is to perform data processing that is not directly provided by xDrip.</p><p>They are only used for Libre sensors and bridges now.</p><p>There are two different families of Out Of Process Algorithms (OOP):</p><h3 id="oop1" tabindex="-1">OOP1 <a class="header-anchor" href="#oop1" aria-label="Permalink to &quot;OOP1&quot;">​</a></h3><img src="'+s+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">Old Android versions ONLY</p><p>Maximum supported Android version is 9.<br> A few Android 10 and above phones have been reported to be functioning with OOP1new/OOP1us.</p></div><table tabindex="0"><thead><tr><th>OOP Version</th><th>Version date</th><th>Supported sensors</th><th>File size</th></tr></thead><tbody><tr><td>OOP1 (2bb9458)</td><td>2018-08-26</td><td>Libre</td><td>17.1MB</td></tr><tr><td>OOP1new (fa218ef)</td><td>2019-11-22</td><td>Libre, Libre 2 EU</td><td>25.3MB</td></tr><tr><td>OOP1us (e901151) - <strong>do not use: use OOP2</strong></td><td>2019-09-13</td><td>Libre 14 days US (old)</td><td>27.8MB</td></tr></tbody></table><p>OOP1 provides readings similar to the vendor reader without calibrating. You need a <a href="./../install/libreBT.html">compatible bridge</a> if using any. OOP1 also applies to NFC scan results.</p><div class="warning custom-block"><p class="custom-block-title">No calibration possible</p><p>Calibrations will be ignored when using OOP1.<br> This is a safety feature as xDrip cannot perform sanity checks on data provided by OOP1.</p></div><p>Two versions are available: <a href="https://drive.google.com/open?id=13ERWcSVSFMLy9rhpbv5rArFrnDuAzriM" target="_blank" rel="noreferrer">Libre 1 and Libre 2 EU</a> or <a href="https://drive.google.com/open?id=172whZZYTyE_ZEuN0T-zhdMKhucy6jP-a" target="_blank" rel="noreferrer">Libre 14 Days US</a>. <em>Note: you need to be logged into your Google account to access the links above</em></p><p>Out Of process Algorithm must be <a href="./misc.html#out-of-process-algorithm">enabled</a> when using OOP1.</p><h3 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2&quot;">​</a></h3><img src="'+a+'" style="zoom:75%;"><p>OOP2 provides decoding for the Libre 14 days US and the Libre 2 EU sensor, either for direct connection (Libre 2 EU only) or using a <a href="./../install/libreBT.html">compatible bridge</a>.</p><div class="info custom-block"><p class="custom-block-title">Calibration is optional</p><p>You can either calibrate from raw data, not calibrate or add a calibration to native data.<br> Check the <a href="./misc.html#oop2">OOP2 settings</a>.</p></div><p><strong>Use only the latest OOP2 app with the latest xDrip version.</strong></p>',16)),e("p",null,[e("strong",null,[e("u",null,[u(r,null,{default:O(()=>[...t[0]||(t[0]=[e("a",{href:"https://drive.google.com/file/d/1106h2s12b3Ev9gKCTU2G75q8h9ChHjcz/view?usp=sharing",target:"_blank",rel:"noreferrer"},"→ Download latest OOP2 here. ←",-1)])]),_:1})])])]),t[2]||(t[2]=o('<p><em>Note: you need to be logged into your Google account to access the link above.</em></p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><em>Out Of process Libre Algorithm</em> (OOP1) must be <a href="./misc.html#out-of-process-algorithm">disabled in xDrip</a> when using OOP2.</p></div><table tabindex="0"><thead><tr><th>OOP Version</th><th>Version date</th><th>Supported sensors</th><th>File size</th></tr></thead><tbody><tr><td>OOP2 (70129ac) - <strong>do not use</strong></td><td>2021-12-04</td><td>Libre 2 EU</td><td>2.63MB</td></tr><tr><td>OOP2new (93e5cac) - <strong>do not use</strong></td><td>2020-12-08</td><td>Libre 14 days US, Libre 2 EU</td><td>2.65MB</td></tr><tr><td>OOP2 1.2 (8a0ee8f) - <strong>do not use</strong></td><td>2022-06-10</td><td>Libre 14 days US (old), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_e6 (6de6678) - <strong>do not use</strong></td><td>2023-01-10</td><td>Libre 14 days US (new), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_more (27da3f5)</td><td>2023-05-25</td><td>Libre 14 days US (new), Libre 2 EU (new)</td><td>2.66MB</td></tr><tr><td>OOP2_c6_09_31 (27da3f5)</td><td>2024-05-31</td><td>Libre 14 days US, Libre 2/2+ EU</td><td>2.7MB</td></tr><tr><td>OOP2-7f0e31 (27da3f5)</td><td>2025-06-12</td><td>Libre 14 days US, Libre 2/2+ EU</td><td>2.73MB</td></tr><tr><td><strong>OOP2-21_9_25 (05d1989)</strong></td><td><strong>2025-09-21</strong></td><td><strong>Libre 14 days US, Libre 2/2+ EU</strong></td><td><strong>2.73MB</strong></td></tr></tbody></table><h3 id="auto-detection" tabindex="-1">Auto-detection <a class="header-anchor" href="#auto-detection" aria-label="Permalink to &quot;Auto-detection&quot;">​</a></h3><p>Some older xDrip versions will detect the presence or necessity of the out of process algorithm.</p><p>Enable <u>only</u> for OOP1.<br><strong>Do not enable for OOP2</strong>. If you enabled it by mistake: <a href="./misc.html#out-of-process-algorithm">disable</a> OOP1.</p><img src="'+i+'" style="zoom:75%;"><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>Use service corresponds to switching ON or OFF the OOP app. If you want to use it, it must be enabled.</p><img src="'+d+'" style="zoom:75%;"><p>Foreground service is an addition that makes it less likely that the app will be put to sleep by the phone. This will not prevent Google Play Protect from stopping it.<br> Enable it if you have data loss (<strong>recommended</strong>).</p><img src="'+n+'" style="zoom:75%;"><p>Direct intent can be enabled if your standalone Wear OS smartwatch requires it (bridge necessary).</p><img src="'+l+'" style="zoom:75%;"><p>You can select the period at which OOP will make sure it&#39;s available.<br> When having data loss you can reduce the interval. The shorter the interval, the more battery use it will require.</p><img src="'+p+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 15/12/2024</em></a></p>',18))])}const U=h(g,[["render",f]]);export{S as __pageData,U as default};
